mapper.select:
select count(*) 
from schedule s
join course c
	on s.course_no = c.course_no
where c.employee_no = #{employeeNo}


and (

	s.schedule_open is null
	or #{schedule.scheduleClose} is null
	or s.schedule_open <= #{schedule.scheduleClose}

)
and (

	s.schedule_close is null
	or #{schedule.scheduleOpen} is null
	or s.schedule_close >= #{schedule.scheduleOpen}

)


and s.schedule_week = #{schedule.scheduleWeek}



and s.schedule_start < #{schedule.scheduleEnd}
and s.schedule_end > #{schedule.scheduleStart}

select count(*) 
from schedule s
where s.classroom_no = #{classroomNo}


and (

	s.schedule_open is null
	or #{schedule.scheduleClose} is null
	or s.schedule_open <= #{schedule.scheduleClose}

)
and (

	s.schedule_close is null
	or #{schedule.scheduleOpen} is null
	or s.schedule_close >= #{schedule.scheduleOpen}

)


and s.schedule_week = #{schedule.scheduleWeek}



and s.schedule_start < #{schedule.scheduleEnd}
and s.schedule_end > #{schedule.scheduleStart}

mapper.update:
update schedule
set schedule_open = #{today}
where schedule_no = #{scheduleNo}

mapper.select:
select * from schedule
where course_no = #{courseNo}
order by schedule_no asc
